CREATE TABLE IF NOT EXISTS vibration (
  id      INTEGER PRIMARY KEY AUTOINCREMENT,
  ts      INTEGER NOT NULL,
  value   REAL    NOT NULL,
  node_id TEXT
);
CREATE INDEX IF NOT EXISTS idx_vibration_ts ON vibration(ts);
CREATE TABLE IF NOT EXISTS app_logs (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  ts        INTEGER NOT NULL,   -- Zeitpunkt in der App (ms)
  received  INTEGER NOT NULL,   -- Eingang bei Node-RED (ms)
  device    TEXT    NOT NULL,   -- Kennung des Handys
  kind      TEXT    NOT NULL,   -- log | error | resolve
  level     TEXT,               -- info | ok | warn | error
  category  TEXT,               -- Scan | Verbindung | Daten | System
  message   TEXT    NOT NULL,
  detail    TEXT,
  error_key TEXT                -- z. B. mqtt, ws, rest
);
CREATE INDEX IF NOT EXISTS idx_app_logs_ts ON app_logs(ts);
CREATE INDEX IF NOT EXISTS idx_app_logs_kind ON app_logs(kind, device, error_key);

