msg.params = {
    $ts: Date.now(),
    $value: msg.payload.value,
    $nodeId: msg.payload.nodeId
};
return msg;

// Standard: 5 Minuten, optional ?minuten=1..60
let minuten = parseInt(msg.req.query.minuten, 10);
if (!Number.isFinite(minuten)) minuten = 5;
minuten = Math.min(60, Math.max(1, minuten));

msg.minuten = minuten;
msg.params = { $since: Date.now() - minuten * 60 * 1000 };
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
const r = (msg.payload && msg.payload[0]) || {};

if (!r.count) {
    msg.statusCode = 404;
    msg.payload = { error: 'Keine Werte in den letzten ' + msg.minuten + ' Minuten', minuten: msg.minuten, count: 0 };
} else {
    msg.statusCode = 200;
    msg.payload = {
        average: r.avg,
        count: r.count,
        min: r.min,
        max: r.max,
        minuten: msg.minuten,
        from: new Date(r.from_ts).toISOString(),
        to: new Date(r.to_ts).toISOString(),
        nodeId: 'ns=2;s=Demo.Alarms.Plant.PowerHouse.P-101.Vibration'
    };
    node.status({ fill: 'blue', shape: 'dot', text: 'Ø ' + r.avg.toFixed(3) + ' aus ' + r.count + ' Werten' });
}
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
// Body kommt als Text (JSON-Array) von der App
let list = msg.payload;
try { if (typeof list === 'string') list = JSON.parse(list); } catch (e) { list = null; }
if (!Array.isArray(list)) list = list && typeof list === 'object' ? [list] : null;

if (!list) {
    msg.statusCode = 400;   // Bad Request
    msg.payload = { error: 'Erwartet wird ein JSON-Array mit Log-Einträgen' };
    return [msg, null];
}

const KINDS = ['log', 'error', 'resolve'];
const LEVELS = ['info', 'ok', 'warn', 'error'];
const cut = (v, n) => v == null ? null : String(v).slice(0, n);
const received = Date.now();

const inserts = list.slice(0, 100)
    .filter(e => e && KINDS.includes(e.kind) && e.msg)
    .map(e => ({
        params: {
            $ts: Number.isFinite(Number(e.t)) ? Number(e.t) : received,
            $received: received,
            $device: cut(e.device || 'unbekannt', 40),
            $kind: e.kind,
            $level: LEVELS.includes(e.level) ? e.level : 'info',
            $category: cut(e.cat, 30),
            $message: cut(e.msg, 300),
            $detail: cut(e.detail, 1000),
            $errorKey: cut(e.key, 40)
        },
        kind: e.kind
    }));

if (inserts.length === 0) {
    msg.statusCode = 400;
    msg.payload = { error: 'Keine gültigen Einträge (kind und msg fehlen)', ignored: list.length };
    return [msg, null];
}

const errors = inserts.filter(i => i.kind === 'error').length;
node.status({ fill: errors ? 'red' : 'green', shape: 'dot',
    text: inserts.length + ' gespeichert' + (errors ? ', ' + errors + ' Fehler' : '') });

msg.statusCode = 200;
msg.payload = { stored: inserts.length, ignored: list.length - inserts.length };

// Ausgang 1: Antwort an die App, Ausgang 2: ein INSERT pro Eintrag
return [msg, inserts];

if (msg.kind !== 'error') return null;
msg.payload = msg.params.$device + ' · ' + msg.params.$message + (msg.params.$detail ? ' – ' + msg.params.$detail : '');
return msg;

const q = msg.req.query;
let limit = parseInt(q.limit, 10);
if (!Number.isFinite(limit)) limit = 50;
limit = Math.min(500, Math.max(1, limit));

msg.params = {
    $limit: limit,
    $kind: ['log', 'error', 'resolve'].includes(q.kind) ? q.kind : null,
    $device: q.device ? String(q.device).slice(0, 40) : null
};
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
msg.statusCode = 200;
msg.payload = (msg.payload || []).map(r => Object.assign(r, {
    time: new Date(r.ts).toISOString()
}));
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
const rows = (msg.payload || []).map(r => Object.assign(r, {
    first: new Date(r.first_ts).toISOString(),
    last: new Date(r.last_ts).toISOString()
}));
msg.statusCode = 200;
msg.payload = { active: rows.length, errors: rows };
node.status({ fill: rows.length ? 'red' : 'green', shape: 'dot', text: rows.length + ' aktive Fehler' });
return msg;
